{
  "findings": [
    {
      "title": "Interim analysis event counts inconsistent with percentages",
      "page": 99,
      "quote": "The first interim efficacy analysis will be performed after observing approximately 238 OS events in SCC patients (70% of total OS events). ... The second interim efficacy analysis will be performed after observing approximately 289 OS events in SCC patients (85% of total OS events). ... The final efficacy analysis will be performed after observing approximately 340 OS events in SCC patients.",
      "severity": "critical"
    },
    {
      "title": "Cross-reference to non-existent Section 4.3 for PK variables",
      "page": 99,
      "quote": "See Section 4.3 for PK variables.",
      "severity": "major"
    },
    {
      "title": "Cross-reference to non-existent Section 4.3.2 for ADA variables",
      "page": 99,
      "quote": "The ADA variables described in Section 4.3.2 will be summarized",
      "severity": "major"
    },
    {
      "title": "Cross-reference to non-existent Section 16.1 for premature termination responsibilities",
      "page": 101,
      "quote": "Investigator and sponsor responsibilities surrounding the premature termination of a study are presented in Section 16.1.",
      "severity": "major"
    },
    {
      "title": "Cross-reference to non-existent Section 9.5.1 for grading scale",
      "page": 98,
      "quote": "TEAEs by severity (according to the grading scale outlined in Section 9.5.1)",
      "severity": "major"
    },
    {
      "title": "Inconsistent definition of treatment period",
      "page": 98,
      "quote": "The treatment period is defined as the day from first dose of study drug to the day of the last dose of study drug plus 90 days, or to the day before the patient commences another anticancer systemic therapy, whichever comes first.",
      "severity": "major"
    },
    {
      "title": "Inconsistent definition of TEAE period",
      "page": 98,
      "quote": "Treatment-emergent adverse events (TEAEs) are defined as those that are not present at baseline or represent the exacerbation of a pre-existing condition during the on-treatment period.",
      "severity": "major"
    },
    {
      "title": "Inconsistent definition of treatment compliance",
      "page": 99,
      "quote": "Treatment compliance, which is defined as (number of doses patients received X scheduled dose interval)/divided by total duration of study drug X 100%",
      "severity": "major"
    },
    {
      "title": "Inconsistent definition of baseline for efficacy vs safety",
      "page": 100,
      "quote": "Unless otherwise specified, the last assessment before the initial administration of cemiplimab will be considered the baseline evaluation for safety measurements. And the last assessment before the randomization will be considered the baseline evaluation for efficacy measurements.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent handling of missing AE start dates",
      "page": 100,
      "quote": "If the start date of an AE or concomitant medication is incomplete or missing, it will be assumed to have occurred on or after the intake of study drug except if an incomplete date (eg, month and year) clearly indicates that the event started prior to treatment. If the partial date indicates the same month or year of the intake of study drug date, then the start date by the study drug intake date will be imputed; otherwise, the missing day or month by the first day or the first month will be imputed.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent handling of multiple lab values per visit",
      "page": 101,
      "quote": "If more than 1 laboratory value is available for a given visit, the first observation will be used in summaries, and all observations will be presented in listings.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent definition of treatment period for TEAE",
      "page": 98,
      "quote": "The treatment period is defined as the day from first dose of study drug to the day of the last dose of study drug plus 90 days, or to the day before the patient commences another anticancer systemic therapy, whichever comes first.",
      "severity": "minor"
    }
  ]
}
